export const generateWarehouseItemCode = (nature, familyOrTypeCode, items = []) => {
  const prefix = (familyOrTypeCode || 'GEN').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const existingWithPrefix = items.filter((item) =>
    (item.id_warehouse_item || '').startsWith(prefix)
  );
  let maxNum = 0;
  existingWithPrefix.forEach((item) => {
    const parts = (item.id_warehouse_item || '').split('-');
    const lastPart = parseInt(parts[parts.length - 1], 10);
    if (!isNaN(lastPart) && lastPart > maxNum) {
      maxNum = lastPart;
    }
  });
  return `${prefix}-${String(maxNum + 1).padStart(3, '0')}`;
};

