export const mapItemToTypeAndDiag = (item) => {
  const text = (item.designation || item.libelle || item.ref || '').toLowerCase();
  if (text.includes('vis') || text.includes('boulon') || text.includes('rondelle') || text.includes('ecrou') || text.includes('cheville')) {
    return { id_type: 'TYPE-FIX', id_diag: 'DIAG-DESSERAGE' };
  }
  if (text.includes('foret') || text.includes('fraise') || text.includes('lame') || text.includes('plaquette') || text.includes('taraud')) {
    return { id_type: 'TYPE-COU', id_diag: 'DIAG-CASSE' };
  }
  if (text.includes('pneu') || text.includes('verin') || text.includes('distributeur') || text.includes('raccord') || text.includes('flexible')) {
    return { id_type: 'TYPE-PNE', id_diag: 'DIAG-FUITE' };
  }
  if (text.includes('moteur') || text.includes('relais') || text.includes('capteur') || text.includes('contacteur') || text.includes('fusible') || text.includes('variateur')) {
    return { id_type: 'TYPE-ELE', id_diag: 'DIAG-SIGNAL' };
  }
  if (text.includes('joint') || text.includes('courroie') || text.includes('bague') || text.includes('filtre') || text.includes('huile')) {
    return { id_type: 'TYPE-CON', id_diag: 'DIAG-DECHIRURE' };
  }
  if (text.includes('cle') || text.includes('tournevis') || text.includes('pince') || text.includes('marteau') || text.includes('douille')) {
    return { id_type: 'TYPE-OUT', id_diag: 'DIAG-USURE' };
  }
  return { id_type: 'TYPE-MEC', id_diag: 'DIAG-USURE' };
};

